using System;using System.IO;using System.Text;using System.Collections;using System.Collections.Generic;using System.Security.Cryptography;using OpenMetaverse;using OpenMetaverse.StructuredData;using OpenSim.Framework;using Animation=OpenSim.Framework.Animation;
namespace OpenSim.Framework{public interface IScene{ISceneObject DeserializeObject(string xml);}public interface ISceneObject{string ToXml2();string ExtraToXmlString();void ExtraFromXmlString(string value);bool HasGroupChanged{get;set;}}}
class DataReference{static UUID Id(int n)=>new UUID("00000000-0000-0000-0000-00000000000"+n);static string H(string s)=>Convert.ToHexString(Encoding.UTF8.GetBytes(s)).ToLowerInvariant();static string Bits(float n)=>(float.IsNaN(n)?0x7fc00000u:BitConverter.SingleToUInt32Bits(n)).ToString("x8");static string Vec(Vector3 v)=>Bits(v.X)+","+Bits(v.Y)+","+Bits(v.Z);static string Quat(Quaternion q)=>Bits(q.X)+","+Bits(q.Y)+","+Bits(q.Z)+","+Bits(q.W);static string Opt(string s)=>s==null?"-":H(s);static string Digest(string s)=>Convert.ToHexString(MD5.HashData(Encoding.UTF8.GetBytes(s))).ToLowerInvariant();class Context{public AgentData owner;public OSDMap command;public string trace="";public int next;public bool mutated;public void Log(string action,int index,string text=""){trace+=action+index+":"+H(text)+";";if(command["failure"].AsString()==action&&command["fail_index"].AsInteger()==index)throw new Exception();}}class Obj:ISceneObject{public Context ctx;public int index;public string xml,extra="initial-extra";public bool changed;public Obj(Context c,int i,string x){ctx=c;index=i;xml=x;}public string ToXml2(){ctx.Log("xml",index);string mode=ctx.command["mutation"].AsString();if(!ctx.mutated&&mode!=""){ctx.mutated=true;if(mode=="add")ctx.owner.AttachmentObjects.Add(new Obj(ctx,9,"new"));else if(mode=="replace")ctx.owner.AttachmentObjects=new();else if(mode=="set_same")ctx.owner.AttachmentObjects[0]=ctx.owner.AttachmentObjects[0];else if(mode=="agent")ctx.owner.AgentID=Id(9);}return xml;}public string ExtraToXmlString(){ctx.Log("extra-to",index);return extra;}public void ExtraFromXmlString(string value){ctx.Log("extra-from",index,value);extra=value;}public bool HasGroupChanged{get{ctx.Log("modified-get",index);return changed;}set{ctx.Log("modified-set",index,value?"1":"0");changed=value;}}}class Scene:IScene{Context ctx;public Scene(Context c){ctx=c;}public ISceneObject DeserializeObject(string xml){int index=ctx.next++;ctx.Log("deserialize",index,xml);return ctx.command["scene_returns_null"].AsBoolean()?null:new Obj(ctx,index,xml);}}
static void Initialize(AgentData p,Context ctx){p.AgentID=Id(7);p.RegionID=Id(9);p.SessionID=Id(8);p.CircuitCode=uint.MaxValue;p.Position=new(1,2,3);p.Velocity=new(4,5,6);p.Center=new(7,8,9);p.Size=new(10,11,12);p.AtAxis=new(13,14,15);p.LeftAxis=new(16,17,18);p.UpAxis=new(19,20,21);p.SenderWantsToWaitForRoot=true;p.Far=123.5f;p.Aspect=1.5f;p.Throttles=new byte[]{1,2,3};p.LocomotionState=123;p.HeadRotation=new(.1f,.2f,.3f,.4f);p.BodyRotation=new(-.1f,-.2f,-.3f,.4f);p.ControlFlags=uint.MaxValue;p.EnergyLevel=.75f;p.GodData=new OSDMap{{"ViewerUiIsGod",OSD.FromBoolean(false)}};p.AlwaysRun=true;p.PreyAgent=Id(5);p.AgentAccess=255;p.ActiveGroupID=Id(6);p.ActiveGroupName="Initial";p.ActiveGroupTitle="Title";p.agentCOF=Id(4);p.CrossingFlags=1;p.CrossExtraFlags=254;p.ChildrenCapSeeds=new(){{9,"nine"},{7,null}};p.Anims=new[]{new Animation(Id(7),1,Id(9))};p.DefaultAnim=new(Id(8),2,Id(9));p.AnimState=new(Id(9),3,Id(9));p.MotionState=3;p.ParentPart=Id(3);p.SitOffset=new(21,22,23);p.Controllers=new[]{new ControllerData(Id(7),Id(8),uint.MaxValue,0x80000000u)};p.CallbackURI="oldcb";p.NewCallbackURI="oldnew";p.AttachmentObjects=new(){new Obj(ctx,0,"<old/>"),new Obj(ctx,1,"<old2/>")};p.AttachmentObjectStates=new(){"oldstate",null};p.MovementAnimationOverRides["Walk"]=Id(7);p.MovementAnimationOverRides["Sit"]=Id(8);p.CachedFriendsOnline=new(){Id(7),UUID.Zero};}
static string State(AgentData p,EntityTransferContext context){string s="";
s+=p.AgentID.ToString()+"|";
s+=p.RegionID.ToString()+"|";
s+=p.SessionID.ToString()+"|";
s+=p.CircuitCode.ToString()+"|";
s+=p.PreyAgent.ToString()+"|";
s+=p.ActiveGroupID.ToString()+"|";
s+=p.agentCOF.ToString()+"|";
s+=p.ParentPart.ToString()+"|";
s+=p.LocomotionState.ToString()+"|";
s+=p.ControlFlags.ToString()+"|";
s+=p.AgentAccess.ToString()+"|";
s+=p.CrossingFlags.ToString()+"|";
s+=p.CrossExtraFlags.ToString()+"|";
s+=p.MotionState.ToString()+"|";
s+=Bits(p.Far)+"|";
s+=Bits(p.Aspect)+"|";
s+=Bits(p.EnergyLevel)+"|";
s+=(p.SenderWantsToWaitForRoot?"1":"0")+"|";
s+=(p.AlwaysRun?"1":"0")+"|";
s+=Vec(p.Position)+"|";
s+=Vec(p.Velocity)+"|";
s+=Vec(p.Center)+"|";
s+=Vec(p.Size)+"|";
s+=Vec(p.AtAxis)+"|";
s+=Vec(p.LeftAxis)+"|";
s+=Vec(p.UpAxis)+"|";
s+=Vec(p.SitOffset)+"|";
s+=Quat(p.HeadRotation)+"|";
s+=Quat(p.BodyRotation)+"|";
s+=Opt(p.ActiveGroupName)+"|";
s+=Opt(p.ActiveGroupTitle)+"|";
s+=Opt(p.CallbackURI)+"|";
s+=Opt(p.NewCallbackURI)+"|";
s+=(p.GodData==null?"-":H(OSDParser.SerializeJsonString(p.GodData,true)))+"|"+(p.Throttles==null?"-":Convert.ToHexString(p.Throttles).ToLowerInvariant())+"|";if(p.ChildrenCapSeeds==null)s+="-";else foreach(var pair in p.ChildrenCapSeeds)s+=pair.Key+":"+Opt(pair.Value)+";";s+="|";Func<Animation,string> animation=a=>a==null?"-":H(OSDParser.SerializeJsonString(a.PackUpdateMessage(),true));if(p.Anims==null)s+="-";else foreach(var a in p.Anims)s+=animation(a)+";";s+="|"+animation(p.DefaultAnim)+"|"+animation(p.AnimState)+"|";if(p.MovementAnimationOverRides==null)s+="-";else foreach(var pair in p.MovementAnimationOverRides)s+=H(pair.Key)+":"+pair.Value+";";s+="|";if(p.Appearance==null)s+="-";else try{s+=Digest(OSDParser.SerializeJsonString(p.Appearance.Pack(context),true));}catch{s+="!";}s+="|";if(p.Controllers==null)s+="-";else foreach(var c in p.Controllers)s+=(c==null?"-":H(OSDParser.SerializeJsonString(c.PackUpdateMessage(),true)))+";";s+="|";if(p.AttachmentObjects==null)s+="-";else foreach(var so in p.AttachmentObjects){var obj=so as Obj;s+=obj==null?"-;":obj.index+":"+H(obj.xml)+":"+H(obj.extra)+":"+(obj.changed?1:0)+";";}s+="|";if(p.AttachmentObjectStates==null)s+="-";else foreach(var value in p.AttachmentObjectStates)s+=Opt(value)+";";s+="|";if(p.CachedFriendsOnline==null)s+="-";else foreach(var id in p.CachedFriendsOnline)s+=id+";";return s;}
static void Main(){Culture.SetCurrentCulture();string line;while((line=Console.ReadLine())!=null){var command=(OSDMap)OSDParser.DeserializeJson(Encoding.UTF8.GetString(Convert.FromHexString(line)));var data=(OSDMap)command["data"];int profile=command["profile"].AsInteger();var ctx=new Context{command=command};AgentData p=(profile&32)!=0?new CompleteAgentData():(profile&16)!=0?new AgentData((Hashtable)null):new AgentData();ctx.owner=p;if((profile&1)!=0)Initialize(p,ctx);var scene=new Scene(ctx);var context=new EntityTransferContext();if(command.ContainsKey("version"))context.OutboundVersion=(float)command["version"].AsReal();if(command["null_context"].AsBoolean())context=null;if(command["null_overrides"].AsBoolean())p.MovementAnimationOverRides=null;bool unpackFailed=false,packFailed=false;string packed="";IAgentData view=p;try{if(!command["skip_unpack"].AsBoolean())view.Unpack(command["null_map"].AsBoolean()?null:data,command["null_scene"].AsBoolean()?null:scene,context);if(command.ContainsKey("look"))p.SetLookAt(Vector3.Parse(command["look"].AsString()));if(command.ContainsKey("interface_id"))view.AgentID=command["interface_id"].AsUUID();if((profile&4)!=0&&data["god_data"] is OSDMap god){god["ViewerUiIsGod"]=OSD.FromBoolean(true);god["after"]=OSD.FromString("source");}}catch{unpackFailed=true;}
if(command.ContainsKey("states_mode")){string mode=command["states_mode"].AsString();if(mode=="null")p.AttachmentObjectStates=null;else if(mode=="empty")p.AttachmentObjectStates=new();else if(mode=="null_object"&&p.AttachmentObjects!=null&&p.AttachmentObjects.Count>0)p.AttachmentObjects[0]=null;}
try{var value=view.Pack(context);if((profile&4)!=0&&p.GodData is OSDMap god){god["ViewerUiIsGod"]=OSD.FromBoolean(false);god["after_pack"]=OSD.FromString("shared");}if((profile&4)!=0&&p.Throttles!=null&&p.Throttles.Length>0)p.Throttles[0]=55;packed=OSDParser.SerializeJsonString(value,true);}catch{packFailed=true;}var output=Console.Out;var dump=new StringWriter();Console.SetOut(dump);p.Dump();Console.SetOut(output);Console.WriteLine((unpackFailed?1:0)+"|"+(packFailed?1:0)+"|"+H(packed)+"|"+H(State(p,context))+"|"+H(ctx.trace)+"|"+H(dump.ToString().Replace("\r\n","\n"))+"|"+view.AgentID);}}}
